package com.sicairos.workstation;
public final class NativePkceTest {
 private static int checks;
 private static void check(boolean ok){checks++;if(!ok)throw new AssertionError("check "+checks);}
 private static void reject(Runnable action){checks++;try{action.run();}catch(IllegalArgumentException expected){return;}throw new AssertionError("accepted invalid callback: "+checks);}
 public static void main(String[] args){check("E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM".equals(NativePkce.challenge("dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk")));NativePkce a=NativePkce.create(1000),b=NativePkce.create(1000);check(!a.nonce.equals(b.nonce)&&!a.verifier.equals(b.verifier));String scheme="com.sicairos.workstation.fullscreentest",callback=a.redirect(scheme)+"&code=test-code";check("test-code".equals(a.callback(callback,scheme,1100).code));check(a.authorize(scheme).contains("code_challenge_method=s256"));check(!a.authorize(scheme).contains(a.verifier));reject(()->a.callback(callback,"com.sicairos.workstation.debug",1100));reject(()->a.callback(callback.replace(a.nonce,b.nonce),scheme,1100));reject(()->a.callback(callback,scheme,999));reject(()->a.callback(callback,scheme,1001+NativePkce.TTL_MS));reject(()->a.callback(callback+"&code=second",scheme,1100));reject(()->a.callback(callback+"&attempt="+a.nonce,scheme,1100));reject(()->a.callback(callback+"#access_token=private",scheme,1100));reject(()->a.callback(callback+"&access_token=private",scheme,1100));reject(()->a.callback(callback.replace("oauth/callback","oauth.evil/callback"),scheme,1100));reject(()->a.callback(callback.replace("oauth/callback","oauth:443/callback"),scheme,1100));reject(()->a.callback(callback.replace("oauth/callback","user@oauth/callback"),scheme,1100));reject(()->a.callback(callback.replace("/callback","/callback/"),scheme,1100));reject(()->a.callback(callback+"&error=denied",scheme,1100));check(a.callback(a.redirect(scheme)+"&error=access_denied",scheme,1100).denied);reject(()->a.callback(a.redirect(scheme),scheme,1100));reject(()->a.callback(callback+"&unknown=x",scheme,1100));reject(()->a.callback(callback.replace("test-code","%GG"),scheme,1100));System.out.println(checks+" native PKCE checks passed");}
}
